  jpeg = NULL;

  messages = cJSON_CreateArray();
  message = cJSON_CreateObject();
  content = cJSON_CreateArray();
  text = cJSON_CreateObject();
  image = cJSON_CreateObject();
  url = cJSON_CreateObject();
