    {
      ret = bk_pm_sleep_mode_set(BK7258_SDK_PM_SUPER_DEEP_SLEEP);
    }

  if (ret == BK_OK)
    {
      syslog(LOG_INFO, "soft-off: entering super-deep; wake gpio=%u\n",
