      printf("bkgpioc0: FAIL %s P%u is internally owned (%d)\n",
             operation, (unsigned int)pin, (int)error);
      return -EBUSY;
    }

  printf("bkgpioc0: FAIL %s P%u error=%d\n",
         operation, (unsigned int)pin, (int)error);
  return -EIO;
}

